const fs = require('fs');
const data = fs.readFileSync(0);
let idx = 0;
const len = data.length;

function nextInt() {
  while (idx < len && data[idx] <= 32) idx++;
  let num = 0;
  while (idx < len && data[idx] > 32) {
    num = num * 10 + (data[idx] - 48);
    idx++;
  }
  return num;
}

const E = nextInt();
const M = nextInt();
const D = nextInt();

const likeX = new Int32Array(M);
const likeY = new Int32Array(M);
for (let i = 0; i < M; i++) {
  likeX[i] = nextInt();
  likeY[i] = nextInt();
}

const disX = new Int32Array(D);
const disY = new Int32Array(D);
for (let i = 0; i < D; i++) {
  disX[i] = nextInt();
  disY[i] = nextInt();
}

const group = new Int32Array(E + 1);
const numGroups = E / 3;
for (let g = 0; g < numGroups; g++) {
  const a = nextInt();
  const b = nextInt();
  const c = nextInt();
  group[a] = g;
  group[b] = g;
  group[c] = g;
}

let violations = 0;
for (let i = 0; i < M; i++) {
  if (group[likeX[i]] !== group[likeY[i]]) violations++;
}
for (let i = 0; i < D; i++) {
  if (group[disX[i]] === group[disY[i]]) violations++;
}

process.stdout.write(violations + '\n');
